//! The styles document of the crate as an embedded asset, with the feature `document-assets` and
//! in the tests of the crate.
//!
//! The table is generated by the build script of the crate from `Styles.xaml` (the counterpart of
//! the embedded resource of the reference project), which it also compiles: the styles are loaded
//! from their compiled markup, and the asset is what lets a document the run-time loader loads
//! include them (`build.rs`).

use crate::ASSEMBLY;
use ferroui_base::platform::register_assets;

include!(concat!(env!("OUT_DIR"), "/assets.rs"));

/// Registers the embedded assets with the asset loader under the name of the assembly of the
/// crate.
pub(crate) fn register() {
    register_assets(ASSEMBLY.name, ASSETS);
}
